const canvasToPNG = canvas => {
  return new Promise(resolve => {
    const img = new Image()
    img.addEventListener('load', () => {
      resolve(img)
    })
    img.src = canvas.toDataURL('image/png')
  })
}

canvasToImage(canvas).then(img => {
